"use strict";
(()=>{
 const login=document.querySelector('#login-form'),register=document.querySelector('#register-form'),logout=document.querySelector('#logout-form'),error=document.querySelector('#auth-error');
 async function submit(path,body,button){button.disabled=true;error.hidden=true;try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'暂时没能完成，请再试一次');location.assign(path==='/api/login'||path==='/api/register'?'/workbench':'/login')}catch(e){error.textContent=e.message;error.hidden=false;error.focus()}finally{button.disabled=false}}
 login?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(login);submit('/api/login',{username:String(f.get('username')),password:String(f.get('password'))},login.querySelector('[type=submit]'))});
 register?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(register);if(f.get('password')!==f.get('password_confirm')){error.textContent='两次密码不一致，请重新确认。';error.hidden=false;error.focus();return}submit('/api/register',{username:String(f.get('username')),password:String(f.get('password')),password_confirm:String(f.get('password_confirm')),test_consent:f.has('test_consent')},register.querySelector('[type=submit]'))});
 if(register||login)fetch('/api/public-settings',{cache:'no-store'}).then(async r=>{if(!r.ok)throw Error();const settings=await r.json();const entry=document.querySelector('#register-link');if(entry)entry.hidden=!settings.registration_open;const message=document.querySelector('#registration-message');if(message)message.textContent=settings.registration_open?'第一次来？注册一个账号，就能开始测试。':'暂未开放自行注册。没有账号或忘记密码，请联系项目负责人。';if(register){document.querySelector('#registration-state').textContent=settings.registration_open?'填好下面三项，注册后会自动打开你的工作台。':'本轮暂未开放注册，请联系项目负责人。';register.querySelector('[type=submit]').disabled=!settings.registration_open;document.querySelector('#demo-consent').hidden=!settings.demo_only;register.elements.test_consent.required=!!settings.demo_only}}).catch(()=>{if(register)document.querySelector('#registration-state').textContent='暂时读不到注册状态，请稍后刷新；尚未创建账号。'});
 document.querySelector('#password-visibility')?.addEventListener('click',e=>{const field=login.elements.password,visible=field.type==='password';field.type=visible?'text':'password';e.target.textContent=visible?'隐藏密码':'显示密码';e.target.setAttribute('aria-pressed',String(visible))});
 logout?.addEventListener('submit',e=>{e.preventDefault();submit('/api/logout',{},logout.querySelector('[type=submit]'))});
 if(logout)fetch('/api/session',{cache:'no-store'}).then(async r=>{if(!r.ok){location.assign('/login');return}const data=await r.json();document.querySelector('#account-name').textContent='当前账号：'+data.user.name}).catch(()=>{document.querySelector('#account-name').textContent='暂时读不到账号，请保持联网后刷新。'});
})();
